#!/usr/bin/env python3
"""
Self-contained sync & installer script for Dream v3.5.0 (Phase M06: Visual Multi-Agent Swarm Neural Mesh & Council Studio).
Applies all backend RPC methods, unit tests, frontend clients, SwarmMeshStudio UI, and 8-locale i18n resources.
"""

import os
import base64
import sys
from pathlib import Path

PAYLOAD = {'docs/ROADMAP_MASTER.md': '', 'dream/bridge/methods_swarm.py': '', 'tests/test_desktop_swarm_bridge.py': '', 'apps/desktop/src/lib/bridge/swarm.ts': '', 'apps/desktop/src/lib/bridge/echo-swarm.ts': '', 'apps/desktop/src/lib/bridge/swarm.test.ts': '', 'apps/desktop/src/components/subagents/swarm-mesh-studio.tsx': '', 'apps/desktop/src/routes/subagents.tsx': '', 'apps/desktop/src/locales/en/subagents.json': '', 'apps/desktop/src/locales/fa/subagents.json': '', 'apps/desktop/src/locales/de/subagents.json': '', 'apps/desktop/src/locales/es/subagents.json': '', 'apps/desktop/src/locales/fr/subagents.json': '', 'apps/desktop/src/locales/ja/subagents.json': '', 'apps/desktop/src/locales/ko/subagents.json': '', 'apps/desktop/src/locales/zh-CN/subagents.json': ''}

def main():
    root = Path(__file__).resolve().parent
    print(f"[*] Applying Dream v3.5.0 (Phase M06) updates to repository at: {root}")
    
    count = 0
    for rel_path, b64_data in PAYLOAD.items():
        target_path = root / rel_path
        target_path.parent.mkdir(parents=True, exist_ok=True)
        raw_bytes = base64.b64decode(b64_data)
        with open(target_path, "wb") as fh:
            fh.write(raw_bytes)
        count += 1
        print(f"  [+] Wrote {rel_path} ({len(raw_bytes):,} bytes)")
        
    print(f"\n[SUCCESS] Successfully installed {count} files for Dream v3.5.0 (Phase M06).")
    print("[*] Ready for git commit and push to main.")

if __name__ == "__main__":
    main()
